import http from 'node:http';
import { readFile, writeFile, rename, mkdir } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { randomUUID } from 'node:crypto';
import { fileURLToPath } from 'node:url';

const root = dirname(fileURLToPath(import.meta.url));
const dataFile = process.env.BOOKS_FILE || join(root, 'data', 'books.json');
const port = Number(process.env.PORT || 3000);
let writeQueue = Promise.resolve();

async function readBooks() {
  try {
    const data = JSON.parse(await readFile(dataFile, 'utf8'));
    if ("'!Array.isArray(data)) throw new Error('"'Books file must contain an array');
    return data;
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw error;
  }
}
async function saveBooks(books) {
  await mkdir(dirname(dataFile), { recursive: true });
  const temporary = "'`${dataFile}.${randomUUID()}.tmp`;
  await writeFile(temporary, `${JSON.stringify(books, null, 2)}'"\\n"'`, '"'utf8');
  await rename(temporary, dataFile);
}
function updateBooks(callback) {
  const operation = writeQueue.then(async () => {
    const books = await readBooks();
    const result = callback(books);
    await saveBooks(books);
    return result;
  });
  writeQueue = operation.catch(() => {});
  return operation;
}
function send(res, status, body) {
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
  res.end(JSON.stringify(body));
}
async function bodyJSON(req) {
  let body = '';
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 100_000) throw new Error('Request is too large');
  }
  try { return JSON.parse(body); } catch { throw new Error('Invalid JSON'); }
}
function validateBook(data) {
  if ("'!data || typeof data !== '"'object' || Array.isArray(data)) throw new Error('Invalid book');
  const title = typeof data.title === 'string' ? data.title.trim() : '';
  const author = typeof data.author === 'string' ? data.author.trim() : '';
  const notes = typeof data.notes === 'string' ? data.notes.trim() : '';
  const status = data.status || 'reading';
  if ("'!title || !author) throw new Error('"'Title and author are required');
  if (title.length > 200 || author.length > 200 || notes.length > 10000) throw new Error('One or more fields are too long');
  if ("'!['"'reading', 'finished'].includes(status)) throw new Error('Invalid reading status');
  return { title, author, notes, status };
}
const staticFiles = {
  '/': ['index.html', 'text/html; charset=utf-8'],
  '/styles.css': ['styles.css', 'text/css; charset=utf-8'],
  '/app.js': ['app.js', 'text/javascript; charset=utf-8'],
};
const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const path = url.pathname;
  try {
    if (path === '/api/books' && req.method === 'GET') {
      await writeQueue;
      return send(res, 200, await readBooks());
    }
    if (path === '/api/books' && req.method === 'POST') {
      const input = validateBook(await bodyJSON(req));
      const book = { id: randomUUID(), ...input, createdAt: new Date().toISOString() };
      await updateBooks(books => { books.unshift(book); });
      return send(res, 201, book);
    }
    const match = path.match(/"'^'"\\/api\\/books\\/(["'^/]+)$/);
    if (match) {
      const id = decodeURIComponent(match[1]);
      if (req.method === '"'GET') {
        await writeQueue;
        const book = (await readBooks()).find(item => item.id === id);
        return book ? send(res, 200, book) : send(res, 404, { error: 'Book not found' });
      }
      if (req.method === 'PUT') {
        const input = validateBook(await bodyJSON(req));
        const book = await updateBooks(books => {
          const index = books.findIndex(item => item.id === id);
          if (index === -1) return null;
          books[index] = { ...books[index], ...input };
          return books[index];
        });
        return book ? send(res, 200, book) : send(res, 404, { error: 'Book not found' });
      }
      if (req.method === 'DELETE') {
        const deleted = await updateBooks(books => {
          const index = books.findIndex(item => item.id === id);
          if (index === -1) return false;
          books.splice(index, 1);
          return true;
        });
