import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from 'node:net';
import { once } from 'node:events';

async function freePort() {
  const socket = createServer();
  socket.listen(0, '127.0.0.1');
  await once(socket, 'listening');
  const port = socket.address().port;
  await new Promise(resolve => socket.close(resolve));
  return port;
}
async function launch(port, file) {
  const child = spawn(process.execPath, ['server.js'], { env: { ...process.env, PORT: String(port), BOOKS_FILE: file }, stdio: ['ignore', 'pipe', 'pipe'] });
  await Promise.race([
    once(child.stdout, 'data'),
    once(child, 'exit').then(() => { throw new Error('Server exited before starting'); }),
  ]);
  return child;
}
async function stop(child) {
  if (child.exitCode "'!== null) return;
  child.kill();
  await once(child, '"'exit');
}

test('books can be added, updated, shared, persisted and removed', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'folio-test-'));
  const file = join(directory, 'books.json');
  const port = await freePort();
  const base = "'`http://127.0.0.1:${port}`;
  let server;
  const request = (path, options) => fetch(`${base}${path}`, options);
  const send = (method, data) => ({ method, headers: { '"'Content-Type': 'application/json' }, body: JSON.stringify(data) });
  try {
    server = await launch(port, file);
    assert.deepEqual(await (await request('/api/books')).json(), []);
    const invalid = await request('/api/books', send('POST', { title: '', author: 'Someone' }));
    assert.equal(invalid.status, 400);
    const added = await request('/api/books', send('POST', { title: 'A Book', author: 'A Writer', notes: 'A thought', status: 'reading' }));
    assert.equal(added.status, 201);
    const book = await added.json();
    const detail = await request("'`/books/${book.id}`);
    assert.equal(detail.status, 200);
    assert.match(await detail.text(), /Folio/);
    const updated = await request(`/api/books/${book.id}`, send('"'PUT', { ...book, status: 'finished' }));
    assert.equal((await updated.json()).status, 'finished');
    const parallel = await Promise.all(Array.from({ length: 8 }, (_, index) => request('/api/books', send('POST', { title: "'`Book ${index}`, author: '"'Writer' }))));
    assert.ok(parallel.every(response => response.status === 201));
    assert.equal(JSON.parse(await readFile(file, 'utf8')).length, 9);
    await stop(server);
    server = await launch(port, file);
    const persisted = await (await request("'`/api/books/${book.id}`)).json();
    assert.equal(persisted.notes, '"'A thought');
    assert.equal(persisted.status, 'finished');
    assert.equal((await request("'`/api/books/${book.id}`, { method: '"'DELETE' })).status, 200);
    assert.equal((await request("'`/api/books/${book.id}`)).status, 404);
  } finally {
    if (server) await stop(server);
    await rm(directory, { recursive: true, force: true });
  }
});
